URL url = new URL("https://api.thingspeak.com/update?api_key=YOUR_API_KEY");
HttpURLConnection conn = (HttpURLConnection) url.openConnection();
conn.setRequestMethod("POST");
conn.setRequestProperty("Content-Type", "application/json");
conn.setDoOutput(true);

String jsonData = "{\"field1\": 20, \"field2\": 33}";
try (OutputStream os = conn.getOutputStream()) {
    byte[] input = jsonData.getBytes("utf-8");
    os.write(input, 0, input.length);
}
int responseCode = conn.getResponseCode();
if (responseCode == HttpURLConnection.HTTP_OK) {
    System.out.println("Gửi dữ liệu thành công lên ThingSpeak.");
}
conn.disconnect();

MqttClient client = new MqttClient("tcp://broker.emqx.io:1883", "JavaClientExample", null);
MqttConnectOptions options = new MqttConnectOptions();
options.setCleanSession(true);

client.setCallback(new MqttCallback() {
    public void connectionLost(Throwable cause) {
        System.out.println("Kết nối bị mất: " + cause.getMessage());
    }
    public void messageArrived(String topic, MqttMessage message) {
        System.out.println("Nhận từ '" + topic + "': " + new String(message.getPayload()));
    }
    public void deliveryComplete(IMqttDeliveryToken token) {
        System.out.println("Gửi thành công!");
    }
});

client.connect(options);
client.subscribe("test/topic");
MqttMessage msg = new MqttMessage("Xin chào từ Java MQTT!".getBytes());
msg.setQos(1);
client.publish("test/topic", msg);

