factory.setHost("localhost");
try (Connection connection = factory.newConnection();
     Channel channel = connection.createChannel()) {
    channel.queueDeclare("ktmt", false, false, false, null);
    String message = "Hello World! Publish message to broker";
    channel.basicPublish("", "ktmt", null, message.getBytes(StandardCharsets.UTF_8));
}

// Consumer
Channel ch = factory.newConnection().createChannel();
ch.queueDeclare("ktmt", false, false, false, null);
DeliverCallback deliverCallback = (consumerTag, delivery) -> {
    String m = new String(delivery.getBody(), "UTF-8");
    System.out.println(" [x] Received '" + m + "'");
};
ch.basicConsume("ktmt", true, deliverCallback, consumerTag -> { });

